1	"use client";
2	
3	import Link from "next/link";
4	import { useState } from "react";
5	
6	/**
7	 * "The right server for every workload" — rocket-style tabbed product picker
8	 * (Cloud VPS · Game Servers · Shared Hosting), each in its own accent colour,
9	 * COMBINED with the pricing chart: a product highlight card (blurb + specs +
10	 * Get started / See all plans) over that product's own 3-tier pricing. Every
11	 * plan is first month free, then renews at the real plan price — the same entry
12	 * price shown on /pricing. All fed by real plans; there is no annual billing.
13	 */
14	export type Tier = { name: string; slug: string; priceCents: number; href: string; specs: [string, string][]; features: string[] };
15	export type Product = {
16	  key: string; label: string; accent: "violet" | "emerald" | "cyan"; href: string;
17	  blurb: string; specs: [string, string][]; tiers: Tier[];
18	};
19	
20	const ACCENT = {
21	  violet: { tab: "from-accent-blue to-brand-500", ring: "ring-brand-500/60", glow: "glow-brand", text: "text-brand-300", dot: "bg-brand-400", badge: "from-accent-blue to-brand-500" },
22	  emerald: { tab: "from-emerald-500 to-teal-500", ring: "ring-emerald-500/60", glow: "shadow-[0_0_44px_-8px_rgba(16,185,129,0.45)]", text: "text-emerald-300", dot: "bg-emerald-400", badge: "from-emerald-500 to-teal-500" },
23	  cyan: { tab: "from-accent-cyan to-accent-blue", ring: "ring-accent-cyan/60", glow: "shadow-[0_0_44px_-8px_rgba(34,211,238,0.45)]", text: "text-accent-cyan", dot: "bg-accent-cyan", badge: "from-accent-cyan to-accent-blue" },
24	};
25	const money = (c: number) => (c / 100).toFixed(c % 100 === 0 ? 0 : 2);
26	
27	export function ProductPricing({ products }: { products: Product[] }) {
28	  const [tab, setTab] = useState(0);
29	  const p = products[tab];
30	  const a = ACCENT[p.accent];
31	  const fromShown = Math.min(...p.tiers.map((t) => t.priceCents));
32	
33	  return (
34	    <div>
35	      {/* product tabs */}
36	      <div className="flex flex-wrap justify-center gap-2">
37	        {products.map((prod, i) => {
38	          const act = i === tab; const ac = ACCENT[prod.accent];
39	          return (
40	            <button key={prod.key} onClick={() => setTab(i)}
41	              className={`flex items-center gap-2 rounded-xl border px-4 py-2 text-sm font-semibold transition-all ${act ? `border-transparent bg-gradient-to-r ${ac.tab} text-white shadow-lg` : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/25 hover:text-white"}`}>
42	              <span className={`h-1.5 w-1.5 rounded-full ${act ? "bg-white" : ac.dot}`} />{prod.label}
43	            </button>
44	          );
45	        })}
46	      </div>
47	
48	      {/* product highlight card (rocket-style) */}
49	      <div className={`mx-auto mt-8 max-w-5xl overflow-hidden rounded-2xl border border-white/[0.08] bg-navy-900/50 ${a.glow}`}>
50	        <div className="grid gap-6 p-6 sm:p-8 lg:grid-cols-[1.05fr_1fr]">
51	          <div className="flex flex-col">
52	            <span className={`inline-flex w-fit items-center gap-1.5 rounded-full bg-gradient-to-r ${a.badge} px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-widest text-white`}>Most popular</span>
53	            <h3 className="mt-3 text-2xl font-bold text-white">{p.label}</h3>
54	            <p className="mt-2 max-w-md text-sm leading-relaxed text-slate-400">{p.blurb}</p>
55	            <p className="mt-5 text-4xl font-bold text-white">
56	              <span className="text-sm font-normal text-slate-500">from </span>${money(fromShown)}<span className="text-sm font-normal text-slate-500">/mo</span>
57	            </p>
58	            <div className="mt-5 flex flex-wrap gap-3">
59	              <Link href="/register" className={`inline-flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r ${a.tab} px-5 py-2.5 text-sm font-semibold text-white transition-[filter] hover:brightness-110`}>Get started →</Link>
60	              <Link href={p.href} className="btn-secondary px-5 py-2.5">See all plans</Link>
61	            </div>
62	          </div>
63	          <div className="rounded-xl border border-white/[0.06] bg-navy-950/50 p-5">
64	            <p className="section-label">Specifications</p>
65	            <dl className="mt-3 divide-y divide-white/[0.05] text-sm">
66	              {p.specs.map(([k, v]) => (
67	                <div key={k} className="flex items-center justify-between py-2">
68	                  <dt className="text-slate-500">{k}</dt><dd className="font-medium text-slate-200">{v}</dd>
69	                </div>
70	              ))}
71	            </dl>
72	          </div>
73	        </div>
74	      </div>
75	
76	      {/* first-month-free banner (single sitewide promo — no annual billing) */}
77	      <div className="mt-10 flex items-center justify-center">
78	        <span className="inline-flex items-center gap-2 rounded-full border border-emerald-500/25 bg-emerald-500/10 px-4 py-1.5 text-sm font-medium text-emerald-300">
79	          <span className="flex h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
80	          First month free on every plan — then the price you sign up at is the price you renew at
81	        </span>
82	      </div>
83	
84	      {/* tiers */}
85	      <div className="mt-8 grid gap-4 lg:grid-cols-3">
86	        {p.tiers.map((t, i) => {
87	          const popular = i === 1;
88	          return (
89	            <div key={t.slug} className={`relative flex flex-col rounded-2xl border p-6 transition-all ${popular ? `scale-[1.02] border-transparent bg-navy-900/70 ring-1 ${a.ring} ${a.glow}` : "border-white/[0.08] bg-navy-900/40"}`}>
90	              {popular && <span className={`absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-gradient-to-r ${a.badge} px-3 py-1 text-[10px] font-bold uppercase tracking-widest text-white shadow-lg`}>Most popular</span>}
91	              <div className="text-[11px] font-semibold uppercase tracking-widest text-slate-500">{t.name}</div>
92	              <div className="mt-2 flex items-end gap-1">
93	                <span className="text-4xl font-bold text-white tabular-nums">${money(t.priceCents)}</span>
94	                <span className="mb-1 text-sm text-slate-500">/mo</span>
95	              </div>
96	              <p className="mt-1 min-h-[16px] text-[11px] text-emerald-300">First month free</p>
97	              <p className="text-[11px] text-slate-500">$0 today, then ${money(t.priceCents)}/mo — never a teaser jump</p>
98	
99	              <dl className="mt-5 space-y-2 border-t border-white/[0.06] pt-4 text-sm">
100	                {t.specs.map(([k, v]) => (
101	                  <div key={k} className="flex items-center justify-between"><dt className="text-slate-500">{k}</dt><dd className="font-medium text-slate-200 tabular-nums">{v}</dd></div>
102	                ))}
103	              </dl>
104	              <ul className="mt-5 space-y-2 border-t border-white/[0.06] pt-4 text-sm text-slate-300">
105	                {t.features.map((f) => <li key={f} className="flex items-start gap-2"><span className={`mt-0.5 ${a.text}`}>✓</span>{f}</li>)}
106	              </ul>
107	              <Link href={t.href} className={`mt-6 inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-all ${popular ? `bg-gradient-to-r ${a.tab} text-white hover:brightness-110` : "border border-white/10 bg-white/[0.04] text-slate-100 hover:border-white/20"}`}>Deploy {t.name}</Link>
108	            </div>
109	          );
110	        })}
111	      </div>
112	
113	      <div className="mt-8 flex flex-col items-center gap-3">
114	        {/* HONESTY: removed a "30-day money-back guarantee — no questions asked" chip.
115	            No such guarantee exists on the site, and this component now renders on the
116	            public, indexable homepage. Keep only the claims below, which are true. */}
117	        <p className="text-center text-sm text-slate-500">No hidden fees · the price you sign up at is the price you renew at · cancel anytime</p>
118	      </div>
119	    </div>
120	  );
121	}
